/*
 * A076827  Number of odd terms minus number of even terms in the set S(n) = (
 *          A002977(k) : k<=n).
 * https://oeis.org/A076827
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (-1)*Sum_{k=1..n} (-1)^A002977(k), where A002977 is
 *            generated by the Klarner-Rado two-pointer merge of 2m+1 and 3m+1
 * Range:     u8 n <= 65, u16 n <= 5063, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 93 terms through n = 9587 (2026-11-07)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/mem.h"

static seq_t *kr_vals = NULL;
static idx_t *kr_odd = NULL;   /* kr_odd[i] = number of odd terms among first i+1 terms */
static idx_t kr_len = 0, kr_cap = 0;
static idx_t kr_i2 = 0, kr_i3 = 0;

static void A076827_grow(idx_t newcap)
{
    seq_t *nv = mem_new(seq_t, (size_t)newcap);
    idx_t *no = (idx_t *)malloc((size_t)newcap * sizeof(idx_t));
    idx_t i;
    for (i = 0; i < kr_len; i++) { nv[i] = kr_vals[i]; no[i] = kr_odd[i]; }
    if (kr_vals) mem_free(kr_vals);
    if (kr_odd) free(kr_odd);
    kr_vals = nv;
    kr_odd = no;
    kr_cap = newcap;
}

seq_t a(idx_t n) {
    if (kr_len == 0) {
        A076827_grow(16);
        kr_vals[0] = 1;
        kr_odd[0] = 1;
        kr_len = 1;
    }
    while (kr_len < n) {
        if (kr_len == kr_cap) A076827_grow(kr_cap * 2);
        seq_t x = kr_vals[kr_i2] * 2 + 1;
        seq_t y = kr_vals[kr_i3] * 3 + 1;
        seq_t m = (x < y) ? x : y;
        if (x == m) kr_i2++;
        if (y == m) kr_i3++;
        kr_vals[kr_len] = m;
        kr_odd[kr_len] = kr_odd[kr_len - 1] + ((m % 2 == 1) ? 1 : 0);
        kr_len++;
    }
    idx_t odd = kr_odd[n - 1];
    return (seq_t)odd * 2 - (seq_t)n;
}
